# <<< SITE-mona END

# Перед сменой сайта удаляем страницы и ресурсы предыдущего варианта.
site_clean() {
    local f
    for f in assets 404.html apple-touch-icon.png docs.html favicon.ico favicon.svg features.html index.html login.html \
             pricing.html privacy.html robots.txt site.webmanifest sitemap.xml terms.html how-it-works.html help.html \
             projects.html approach.html field-notes.html calendar.html guide.html paddock.html \
             studio.html estimate.html formats.html formats cases.html cases delivery.html prepare.html archive-help.html planning.html sample-files.html listening-guide.html \
             build.html parts.html catalog.html catalog builds.html builds compare.html; do
        rm -rf "${WEBROOT:?}/${f}"
    done
}

write_html() {
    site_clean
    case "${SITE}" in
        zro)       write_html_zro ;;
        mona)      write_html_mona ;;
        stillform) write_html_stillform ;;
        apex)      write_html_apex ;;
        archive)   write_html_archive ;;
        keyform)   write_html_keyform ;;
    esac
    info "Сайт: ${SITE}"
}

